from PIL import Image
def blobs(f):
    im=Image.open(f).convert("L"); w,h=im.size; px=im.load()
    seen=set(); out=[]
    import collections
    for y in range(h):
        for x in range(w):
            if px[x,y]<100 and (x,y) not in seen:
                q=collections.deque([(x,y)]); seen.add((x,y)); pts=[]
                while q:
                    a,b=q.popleft(); pts.append((a,b))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=a+dx,b+dy
                        if 0<=nx<w and 0<=ny<h and (nx,ny) not in seen and px[nx,ny]<100:
                            seen.add((nx,ny)); q.append((nx,ny))
                if 30<len(pts)<3000:
                    xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                    out.append((len(pts),sum(xs)/len(xs),sum(ys)/len(ys)))
    return out
for f in ["captures/wrist_002.png","captures/wrist_003.png","captures/wrist_004.png"]:
    print(f, [(n,round(cx,1),round(cy,1)) for n,cx,cy in blobs(f)])
EOF

